// UI texts in German and English. Language: cookie "ew_lang" (also read by the server) > stored choice > browser.
// Switching the language reloads the page so every view, the map and server-rendered texts change together.

const KEY = "emberwatch.lang";
export const LANGS = ["de", "en"];

function cookieLang() {
  const m = document.cookie.match(/(?:^|;\s*)ew_lang=(de|en)(?:;|$)/);
  return m ? m[1] : null;
}

function detect() {
  let stored = null;
  try { stored = localStorage.getItem(KEY); } catch { /* ignore */ }
  const nav = (navigator.languages && navigator.languages[0]) || navigator.language || "en";
  return cookieLang() || (LANGS.includes(stored) ? stored : null) || (nav.toLowerCase().startsWith("de") ? "de" : "en");
}

export const lang = detect();
export const locale = lang === "de" ? "de-DE" : "en-GB";
document.documentElement.lang = lang;
// keep the cookie in sync so server-rendered texts (patterns, alerts, errors) match the UI
if (cookieLang() !== lang) document.cookie = `ew_lang=${lang}; path=/; max-age=31536000; SameSite=Strict`;

export function setLang(l) {
  if (!LANGS.includes(l)) return;
  try { localStorage.setItem(KEY, l); } catch { /* ignore */ }
  document.cookie = `ew_lang=${l}; path=/; max-age=31536000; SameSite=Strict`;
  window.location.reload();
}

