export function t(key, params = {}) {
  const tpl = T[lang][key] ?? T.en[key] ?? key;
  return tpl.replace(/\{(\w+)\}/g, (m, k) => (params[k] === undefined || params[k] === null ? m : String(params[k])));
}

/** Applies data-i18n* attributes of static markup. */
export function applyStatic(root = document) {
  for (const n of root.querySelectorAll("[data-i18n]")) n.textContent = t(n.dataset.i18n);
  for (const [attr, name] of [["i18nTitle", "title"], ["i18nPlaceholder", "placeholder"], ["i18nAria", "aria-label"]]) {
    for (const n of root.querySelectorAll(`[data-${attr.replace(/[A-Z]/g, (c) => "-" + c.toLowerCase())}]`)) n.setAttribute(name, t(n.dataset[attr]));
  }
}
